/* ---------- shader patch: narrow light sweep ("sheen") across the finished card ---------- */
const SHEEN = {
  uSheenAxis: { value: new THREE.Vector3(0, 0, 1) },
  uSheenPos: { value: -1e9 },
  uSheenAmt: { value: 0 },
  uSheenW: { value: 18 },
};
function addSheen(mat) {
  mat.onBeforeCompile = (sh) => {
    Object.assign(sh.uniforms, SHEEN);
    sh.vertexShader = 'varying vec3 vSheenW;\n' + sh.vertexShader.replace('#include <project_vertex>', `#include <project_vertex>
      vec4 shw = vec4(transformed, 1.0);
      #ifdef USE_INSTANCING
        shw = instanceMatrix * shw;
      #endif
      vSheenW = (modelMatrix * shw).xyz;`);
    sh.fragmentShader = 'uniform vec3 uSheenAxis; uniform float uSheenPos; uniform float uSheenAmt; uniform float uSheenW; varying vec3 vSheenW;\n' +
      sh.fragmentShader.replace('#include <opaque_fragment>', `
      {
        float sd = dot(vSheenW, uSheenAxis) - uSheenPos;
        float sb = exp(-sd * sd / (uSheenW * uSheenW));
        float fr = pow(1.0 - clamp(abs(dot(normalize(normal), normalize(vViewPosition))), 0.0, 1.0), 1.4);
        outgoingLight += vec3(0.92, 0.96, 1.0) * sb * uSheenAmt * (0.18 + 0.82 * fr);
      }
      #include <opaque_fragment>`);
  };
  mat.customProgramCacheKey = () => 'sheen';
  return mat;
}

