// local contrast, fine detector noise and faint scan lines. The green on/off highlights stay in colour, as in an
// annotated micrograph. uSem blends it in and out (0 = the normal colour image).
const SEM = {
  uniforms: {
    tDiffuse: { value: null }, tDepth: { value: gtao.depthTexture }, uNear: { value: 0.1 }, uFar: { value: 100 },
    uTexel: { value: new THREE.Vector2(1, 1) }, uSem: { value: 0 }, uSeed: { value: 0 }, uEdge: { value: 1 },
  },
  vertexShader: 'varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }',
  fragmentShader: `
    #include <packing>
    uniform sampler2D tDiffuse; uniform sampler2D tDepth; uniform float uNear; uniform float uFar; uniform vec2 uTexel;
    uniform float uSem; uniform float uSeed; uniform float uEdge; varying vec2 vUv;
    float linZ(vec2 uv) { float d = texture2D(tDepth, uv).x; return perspectiveDepthToViewZ(d, uNear, uFar) * -1.0; }
    float h(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233)) + uSeed) * 43758.5453); }
    float lum(vec3 c) { return dot(c, vec3(0.299, 0.587, 0.114)); }
