                       + lum(texture2D(tDiffuse, vUv + vec2(0.0, uTexel.y)).rgb) + lum(texture2D(tDiffuse, vUv - vec2(0.0, uTexel.y)).rgb));
      Ln = Ln / (Ln + 0.5);
      float z = linZ(vUv);
      vec2 o = uTexel * 1.5;
      float zx = linZ(vUv + vec2(o.x, 0.0)) - linZ(vUv - vec2(o.x, 0.0)), zy = linZ(vUv + vec2(0.0, o.y)) - linZ(vUv - vec2(0.0, o.y));
